public class Main {
    public static void main(String[] args) {
        int bayar = 20000;
        int total = 17000;
        if (bayar >= total) {
            System.out.println("Kembalian: " + (bayar - total));
        } else {
            System.out.println("Uang kurang");
        }
    }
}

public class Main {
    public static void main(String[] args) {
        int bayar = 20000;
        int total = 17000;
        if (bayar >= total) {
            System.out.println("Kembalian: " + (bayar - total));
        } else {
            System.out.println("Uang kurang");
        }
        if (total >= 100000) {
            System.out.println("Pembeli besar");
        } else if (total >= 50000) {
            System.out.println("Pembeli sedang");
        } else {
            System.out.println("Pembeli biasa");
        }
    }
}

public class Main {
    public static void main(String[] args) {
        int bayar = 15000;
        int total = 17000;
        if (bayar >= total) {
            System.out.println("Kembalian: " + (bayar - total));
        } else {
            System.out.println("Uang kurang " + (total - bayar));
        }
        if (total >= 100000) {
            System.out.println("Pembeli besar");
        } else if (total >= 50000) {
            System.out.println("Pembeli sedang");
        } else {
            System.out.println("Pembeli biasa");
        }
    }
}

